// PlugAI project — ESP32-C3-DevKitM-1 (ESP-IDF v5.5)
// SOS light: repeating pattern on a single LED (GPIO4 -> 220R -> LED anode, cathode -> GND)
//
// Cycle (3750 ms):
//   3 fast blinks : ON 150 / OFF 150  (x3)
//   1 s pause     : OFF 1000
//   2 slow blinks : ON 500 / OFF 500  (x2)
//   -> loop forever
#include <stdio.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "driver/gpio.h"
#include "esp_timer.h"
#include "esp_log.h"

static const char *TAG = "SOS";

#define LED_GPIO GPIO_NUM_4

typedef struct {
    int level;   /* 1 = on, 0 = off */
    int ms;      /* duration in milliseconds */
} step_t;

/* One full SOS cycle, 3750 ms total. */
static const step_t sos_pattern[] = {
    { 1,  150 },   /* fast blink 1 on  */
    { 0,  150 },   /* fast blink 1 off */
    { 1,  150 },   /* fast blink 2 on  */
    { 0,  150 },   /* fast blink 2 off */
    { 1,  150 },   /* fast blink 3 on  */
    { 0, 1000 },   /* pause            */
    { 1,  500 },   /* slow blink 1 on  */
    { 0,  500 },   /* slow blink 1 off */
    { 1,  500 },   /* slow blink 2 on  */
    { 0,  500 },   /* slow blink 2 off */
};

#define SOS_STEPS (sizeof(sos_pattern) / sizeof(sos_pattern[0]))

void app_main(void)
{
    gpio_config_t io_conf = {
        .pin_bit_mask = (1ULL << LED_GPIO),
        .mode = GPIO_MODE_OUTPUT,
        .pull_up_en = GPIO_PULLUP_DISABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type = GPIO_INTR_DISABLE,
    };
    ESP_ERROR_CHECK(gpio_config(&io_conf));

    /* Start with the LED off. */
    gpio_set_level(LED_GPIO, 0);

    printf("PlugAI: SOS light pattern started\n");
    ESP_LOGI(TAG, "SOS light pattern started (GPIO%d, cycle 3750 ms)", LED_GPIO);

    uint32_t cycle = 0;
    while (1) {
        int64_t t0 = esp_timer_get_time();
        for (size_t i = 0; i < SOS_STEPS; i++) {
            gpio_set_level(LED_GPIO, sos_pattern[i].level);
            vTaskDelay(pdMS_TO_TICKS(sos_pattern[i].ms));
        }
        cycle++;
        ESP_LOGD(TAG, "cycle %lu done in %lld us", (unsigned long)cycle,
                 (long long)(esp_timer_get_time() - t0));
    }
}

